"""Small, standard-library-only client for OpenAI's Responses API.

The client does not log or persist prompts.  Set ``OPENAI_API_KEY`` in the
environment (or pass ``api_key`` explicitly) before calling ``send_prompt``.
"""

from __future__ import annotations

import json
import os
import ssl
from typing import Any, Dict, Optional
from urllib.error import HTTPError, URLError
from urllib.request import Request, urlopen


API_URL = "https://api.openai.com/v1/responses"
DEFAULT_MODEL = "gpt-4.1-mini"


class OpenAIError(RuntimeError):
    """An error returned by, or encountered while calling, the API."""

    def __init__(
        self,
        message: str,
        *,
        status_code: Optional[int] = None,
        request_id: Optional[str] = None,
    ) -> None:
        super().__init__(message)
        self.status_code = status_code
        self.request_id = request_id


def create_response(
    prompt: str,
    *,
    model: Optional[str] = None,
    api_key: Optional[str] = None,
    instructions: Optional[str] = None,
    timeout: float = 60.0,
    max_output_tokens: Optional[int] = None,
    store: bool = False,
    endpoint: str = API_URL,
) -> Dict[str, Any]:
    """Send one private text prompt and return the decoded API response.

    ``store`` defaults to ``False`` so the request asks the API not to retain
    the response for later retrieval.  This function intentionally never
    prints the prompt or response.
    """
    if not isinstance(prompt, str) or not prompt.strip():
        raise ValueError("prompt must be a non-empty string")
    if timeout <= 0:
        raise ValueError("timeout must be greater than zero")
    if max_output_tokens is not None and max_output_tokens <= 0:
        raise ValueError("max_output_tokens must be greater than zero")

    secret = api_key or os.environ.get("OPENAI_API_KEY")
    if not secret:
        raise OpenAIError("Set OPENAI_API_KEY or pass api_key explicitly")

    payload: Dict[str, Any] = {
        "model": model or os.environ.get("OPENAI_MODEL", DEFAULT_MODEL),
        "input": prompt,
        "store": bool(store),
    }
    if instructions is not None:
        payload["instructions"] = instructions
    if max_output_tokens is not None:
        payload["max_output_tokens"] = max_output_tokens

    body = json.dumps(payload, ensure_ascii=False).encode("utf-8")
    request = Request(
        endpoint,
        data=body,
        headers={
            "Authorization": "Bearer " + secret,
            "Content-Type": "application/json",
            "Accept": "application/json",
        },
        method="POST",
    )

    try:
        with urlopen(request, timeout=timeout, context=ssl.create_default_context()) as reply:
            raw = reply.read()
            return _decode_json(raw, reply.headers.get("x-request-id"))
    except HTTPError as exc:
        raw = exc.read()
        message = _api_error_message(raw) or "OpenAI API request failed"
        raise OpenAIError(
            message,
            status_code=exc.code,
            request_id=exc.headers.get("x-request-id"),
        ) from None
    except (URLError, TimeoutError, OSError) as exc:
        raise OpenAIError("Could not reach the OpenAI API") from exc


def send_prompt(prompt: str, **kwargs: Any) -> str:
    """Send ``prompt`` and return the text produced by the model."""
    return response_text(create_response(prompt, **kwargs))


def response_text(response: Dict[str, Any]) -> str:
    """Extract assistant text from a Responses API response.

    This handles the current ``output[].content[].text`` shape and ignores
    non-text output items such as tool calls.
    """
    parts = []
    for item in response.get("output", []):
        for content in item.get("content", []):
            if content.get("type") in ("output_text", "text") and isinstance(content.get("text"), str):
                parts.append(content["text"])
    return "".join(parts)


def _decode_json(raw: bytes, request_id: Optional[str]) -> Dict[str, Any]:
    try:
        value = json.loads(raw.decode("utf-8"))
    except (UnicodeDecodeError, json.JSONDecodeError) as exc:
        raise OpenAIError("OpenAI returned invalid JSON", request_id=request_id) from exc
    if not isinstance(value, dict):
        raise OpenAIError("OpenAI returned an unexpected response", request_id=request_id)
    return value


def _api_error_message(raw: bytes) -> Optional[str]:
    try:
        value = json.loads(raw.decode("utf-8"))
        error = value.get("error", {})
        message = error.get("message")
        return message if isinstance(message, str) else None
    except (UnicodeDecodeError, json.JSONDecodeError, AttributeError):
        return None


__all__ = ["OpenAIError", "create_response", "response_text", "send_prompt"]
